<section class="table-card">
    <div class="card-head"><h2>Sales Report</h2><div class="button-row"><button class="btn btn-outline btn-sm" onclick="window.print()">Print</button><a class="btn btn-outline btn-sm" href="<?= url('admin/export', ['from'=>$from, 'to'=>$to]) ?>">CSV / Excel</a><button class="btn btn-outline btn-sm" onclick="window.print()">PDF</button></div></div>
    <form class="admin-filters" method="get" action="<?= url('admin/reports') ?>"><label>From<input type="date" name="from" value="<?= h($from) ?>"></label><label>To<input type="date" name="to" value="<?= h($to) ?>"></label><select><option>Sales Report</option><option>Product-wise Report</option><option>Customer Report</option></select><button class="btn btn-primary btn-sm">Run</button></form>
    <div class="stats-grid small"><div class="stat-card"><p>Orders</p><strong><?= array_sum(array_column($rows, 'orders')) ?></strong></div><div class="stat-card"><p>Sales</p><strong><?= money(array_sum(array_column($rows, 'total'))) ?></strong></div><div class="stat-card"><p>Discounts</p><strong><?= money(array_sum(array_column($rows, 'discounts'))) ?></strong></div></div>
    <table class="data-table"><thead><tr><th>Date</th><th>Orders</th><th>Subtotal</th><th>Discounts</th><th>Total</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= h($row['sale_date']) ?></td><td class="num"><?= h($row['orders']) ?></td><td class="num"><?= money($row['subtotal']) ?></td><td class="num"><?= money($row['discounts']) ?></td><td class="num"><?= money($row['total']) ?></td></tr><?php endforeach; ?></tbody></table>
</section>
